/**
 * Built-in clipart browser.
 *
 * The catalogue is generated by the engine, not loaded from an SVG pack, so
 * every shape is original and can be inserted without a network request. A
 * shape is placed as a normal complex fill: it is fully editable afterwards
 * and carries no special "clipart" state.
 */

import { useMemo, useState } from 'react';
import type React from 'react';
import {
  CLIPART_CATEGORIES,
  placeClipart,
  searchClipart,
  type ClipartEntry,
} from '@threadworks/engine';
import { useDesignStore } from '../store/designStore.js';
import { referenceStore } from '../store/referenceStore.js';
import { createObject } from '../model/defaults.js';

export interface ClipartBrowserProps {
  onClose: () => void;
  notify: (message: string, isError?: boolean) => void;
}

function pathFor(entry: ClipartEntry): string {
  return entry.rings
    .map((ring) =>
      ring
        .map((point, index) => `${index === 0 ? 'M' : 'L'}${point.x.toFixed(4)} ${point.y.toFixed(4)}`)
        .join(' ') + ' Z',
    )
    .join(' ');
}

export function ClipartBrowser({ onClose, notify }: ClipartBrowserProps): React.ReactElement {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>('heart');
  const [widthMm, setWidthMm] = useState(40);
  const [heightMm, setHeightMm] = useState(40);

  const design = useDesignStore((s) => s.design);
  const addObject = useDesignStore((s) => s.addObject);
  const defaultStitchType = referenceStore((s) => s.settings?.defaultStitchType ?? 'tatami');

  const results = useMemo(() => searchClipart(query, category), [query, category]);
  const selected = results.find((entry) => entry.id === selectedId) ?? results[0] ?? null;

  const add = (): void => {
    if (!selected) return;
    const placed = placeClipart(selected.id, {
      widthMm,
      heightMm,
      center: { x: design.width / 2, y: design.height / 2 },
    });
    if (!placed) {
      notify('That clipart shape could not be placed.', true);
      return;
    }
    const object = createObject(
      'fill',
      placed.rings,
      0,
      design.objects.length,
      selected.id === 'leaf' ? 'tatami' : defaultStitchType,
    );
    addObject({
      ...object,
      name: placed.name,
      machine: 1,
    });
    notify(`Added ${placed.name} at ${placed.widthMm.toFixed(1)} x ${placed.heightMm.toFixed(1)} mm.`);
    onClose();
  };

  return (
    <div className="modal-backdrop" role="presentation" onClick={onClose}>
      <div
        className="modal clipart-browser"
        role="dialog"
        aria-modal="true"
        aria-label="Clipart"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="modal-header">
          <h2>Clipart</h2>
          <button type="button" onClick={onClose} aria-label="Close">
            &times;
          </button>
        </div>

        <p className="dialog-hint">
          Original built-in shapes. Inserting one adds an editable complex fill to the current design;
          resize it on the canvas or with the inspector afterwards.
        </p>

        <div className="clipart-controls">
          <label className="field">
            <span>Search</span>
            <input
              type="search"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="star, leaf, pet..."
              data-testid="clipart-search"
            />
          </label>
          <label className="field">
            <span>Category</span>
            <select
              value={category ?? ''}
              onChange={(event) => setCategory(event.target.value === '' ? null : event.target.value)}
              data-testid="clipart-category"
            >
              <option value="">All categories</option>
              {CLIPART_CATEGORIES.map((name) => (
                <option key={name} value={name}>
                  {name}
                </option>
              ))}
            </select>
          </label>
        </div>

        <div className="clipart-body">
          <ul className="clipart-grid" data-testid="clipart-grid">
            {results.map((entry) => (
              <li key={entry.id}>
                <button
                  type="button"
                  className={entry.id === selected?.id ? 'clipart-tile selected' : 'clipart-tile'}
                  onClick={() => setSelectedId(entry.id)}
                  aria-pressed={entry.id === selected?.id}
                  data-testid={`clipart-${entry.id}`}
                >
                  <svg viewBox="-0.55 -0.55 1.1 1.1" width={54} height={54} aria-hidden="true">
                    <path d={pathFor(entry)} fill="currentColor" fillRule="evenodd" />
                  </svg>
                  <span>{entry.name}</span>
                  <small>{entry.category}</small>
                </button>
              </li>
            ))}
          </ul>
          {results.length === 0 && <p className="empty-state">No shapes match that search.</p>}

          <div className="clipart-detail">
            {selected ? (
              <>
                <svg viewBox="-0.55 -0.55 1.1 1.1" width={112} height={112} aria-hidden="true">
                  <path d={pathFor(selected)} fill="#d7d2c7" fillRule="evenodd" />
                </svg>
                <h3>{selected.name}</h3>
                <p className="muted small">{selected.tags.join(' · ')}</p>
                <div className="field-pair">
                  <label className="field">
                    <span>Width (mm)</span>
                    <input
                      type="number"
                      min="1"
                      max="500"
                      value={widthMm}
                      onChange={(event) => setWidthMm(Number(event.target.value))}
                    />
                  </label>
                  <label className="field">
                    <span>Height (mm)</span>
                    <input
                      type="number"
                      min="1"
                      max="500"
                      value={heightMm}
                      onChange={(event) => setHeightMm(Number(event.target.value))}
                    />
                  </label>
                </div>
                <button type="button" onClick={add} data-testid="clipart-add">
                  Add to design
                </button>
              </>
            ) : (
              <p className="muted">Pick a shape.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
